#!/usr/bin/env node
// bundle-editor-data.mjs — copy the two generator-emitted, server-only bundles
// into the Worker's import tree so wrangler inlines them into the deployed bundle:
//
//   build/editor-map.generated.json         -> app/worker/editor-data/editor-map.generated.json
//   build/instructor-bundle.generated.json  -> app/worker/editor-data/instructor-bundle.generated.json
//
// These are the universal allowlist (editor-map) + the server-only instructor
// materials (facts/notes/answer keys). Both are gitignored throwaway artifacts,
// regenerated by the Python generators. This script is wired as wrangler's
// build.command (wrangler.jsonc) so it runs automatically before every
// deploy/dry-run, and it is run before `node --test` so editor-map.js can import.
//
// If a source bundle is missing, we FAIL LOUD — a stale/empty allowlist must
// never ship. Regenerate with:
//   python3 tools/build_site.py --check && python3 tools/build_instructor_bundle.py

import { mkdirSync, copyFileSync, existsSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const here = dirname(fileURLToPath(import.meta.url));
const workerDir = join(here, "..");
const repoRoot = join(workerDir, "..", "..");
const outDir = join(workerDir, "editor-data");

const FILES = [
  ["build/editor-map.generated.json", "editor-map.generated.json"],
  ["build/instructor-bundle.generated.json", "instructor-bundle.generated.json"],
  // Editor-gated redline History bundle (build_history.py). Inlined so the Worker
  // serves per-doc history slices at /edit/history/<slug> exactly like the map.
  ["build/history-bundle.generated.json", "history-bundle.generated.json"],
];

// The history bundle (unlike the editor-map/instructor bundles) is NOT produced
// by build_site/build_instructor_bundle, so the apply engine's per-apply worker
// deploy (which rebuilds map/instructor in its worktree but not history) would
// otherwise find it MISSING and fail loud. build.command must be self-sufficient:
// generate the history bundle here if it is absent (build_history reads this
// tree's git log). Callers that want it FRESH (the daemon rebuild step) regen it
// explicitly beforehand; this is the presence guarantee, not a freshness one.
const historyBundle = join(repoRoot, "build/history-bundle.generated.json");
if (!existsSync(historyBundle)) {
  console.log("bundle-editor-data: history bundle absent — running build_history.py …");
  const r = spawnSync("python3", [join(repoRoot, "tools/build_history.py")],
    { cwd: repoRoot, stdio: "inherit" });
  if (r.status !== 0 || !existsSync(historyBundle)) {
    console.error("bundle-editor-data: build_history.py did not produce a bundle — history will ship EMPTY.");
    // Non-fatal: write a valid empty bundle so the Worker route degrades to
    // "no history available" instead of breaking the whole deploy.
    mkdirSync(dirname(historyBundle), { recursive: true });
    writeFileSync(historyBundle, JSON.stringify({
      sentinel: "SONSTENG-HISTORY-EDITOR-GATED", docs: {}, generated_at: new Date().toISOString(),
    }));
  }
}

mkdirSync(outDir, { recursive: true });
let ok = true;
for (const [src, dest] of FILES) {
  const from = join(repoRoot, src);
  const to = join(outDir, dest);
  if (!existsSync(from)) {
    console.error(`bundle-editor-data: MISSING ${src} — run the generators first.`);
    ok = false;
    continue;
  }
  copyFileSync(from, to);
  const kb = Math.round(statSync(to).size / 1024);
  console.log(`bundle-editor-data: ${src} -> editor-data/${dest} (${kb} KB)`);
}
if (!ok) process.exit(1);

// Emit the real editor CLIENT (app/editor/editor.{js,css}) as an importable JS
// module so wrangler inlines it into the deployed bundle and the Worker serves
// it verbatim at /edit/assets/* (CSP script-src 'self', no inline). Missing
// client files is non-fatal — editor-assets.js falls back to its built-in stubs
// (used by unit tests, which don't need the full contenteditable UX).
import { readFileSync } from "node:fs";
const CLIENT = [
  ["app/editor/editor.js", "EDITOR_JS"],
  ["app/editor/editor.css", "EDITOR_CSS"],
  // Redline History browser client (served at /edit/assets/history.*).
  ["app/history/history.js", "HISTORY_JS"],
  ["app/history/history.css", "HISTORY_CSS"],
];
const parts = [
  "// AUTO-GENERATED by bundle-editor-data.mjs — do not edit. Source: app/editor/.",
];
let clientOk = true;
for (const [src, name] of CLIENT) {
  const from = join(repoRoot, src);
  if (!existsSync(from)) { clientOk = false; continue; }
  parts.push(`export const ${name} = ${JSON.stringify(readFileSync(from, "utf8"))};`);
}
if (clientOk) {
  writeFileSync(join(outDir, "editor-client.generated.js"), parts.join("\n") + "\n");
  console.log("bundle-editor-data: app/editor/editor.{js,css} -> editor-data/editor-client.generated.js");
} else {
  // Write an empty module so the static import in editor-assets.js always resolves.
  writeFileSync(join(outDir, "editor-client.generated.js"),
    "// client bundle absent at build time — editor-assets.js uses its stubs\n");
  console.log("bundle-editor-data: client absent — wrote empty editor-client module (stubs in use)");
}
